DO $dadyoom$
DECLARE r RECORD; target_id uuid; prior text; nact integer; hasprogress integer;
BEGIN
 FOR r IN SELECT * FROM jsonb_to_recordset('[{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"2b543444-bfe4-4c5a-a82d-66063fc3fc9f","n":1,"title":"السرد في الأدب العربي الحديث","passage":"يحلل السرد من جهة الراوي وزاوية الرؤية والشخصيات والزمان والمكان وتسلسل الأحداث، مع تمييز صوت الراوي من رأي المؤلف. في قصة أصلية يبحث طفل عن كتاب ضائع، ويتدرج من الخطأ إلى المراجعة حتى يجده؛ التحول نتيجة أفعال الشخصية.","question":"ما العنصر الذي ينظم نقل الأحداث للقارئ؟","correct":"الراوي وزاوية السرد","wrong":["حرف الجر وحده","وزن البيت","إعراب المصدر"],"practice":"حلل نصًا سرديًا صحيح المصدر مع تحديد الراوي والعقدة والتحول.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"2b543444-bfe4-4c5a-a82d-66063fc3fc9f","n":2,"title":"فن السيرة","passage":"تعرض السيرة جانبًا من حياة شخص عبر اختيار أحداث ووثائق ووجهة نظر، ويختلف توثيق الوقائع عن بناء المشاهد الأدبي. لا يجوز اختلاق قول لشخصية تاريخية لملء الفراغات. في مثال مستقل يجمع باحث تواريخ وصورًا مأذونة قبل صياغة بطاقة سيرة.","question":"ما الشرط الأساسي لكتابة سيرة موثوقة؟","correct":"التحقق من الأحداث والمصادر","wrong":["اختلاق حوار تاريخي","تخمين المواعيد","إهمال الزمن"],"practice":"أعد بطاقة سيرة لمؤلف أدبي تتضمن عملًا صحيحًا وتواريخ مثبتة ومراجع.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"2b543444-bfe4-4c5a-a82d-66063fc3fc9f","n":3,"title":"الأيام لطه حسين","passage":"«الأيام» عمل سردي لطه حسين يتطلب قراءة النص المقرر للتعرف إلى طريقة بناء الذاكرة والراوي والشخصيات، ولا يجوز تلفيق جمل منسوبة إليه. مثال أصلي يروي متعلم ذكرى يومه الأول في مكتبة ويناقش الفرق بين الحدث وذاكرته عنه.","question":"ما الذي يضبط تحليل الذاكرة في سرد السيرة؟","correct":"شواهد النص ومنظور الراوي","wrong":["افتراض حوادث غير مذكورة","نقل اقتباس مختلق","العنوان وحده"],"practice":"اقرأ مقطعًا صحيحًا من «الأيام» واستخرج أثر زاوية السرد في فهم الحدث.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"2b543444-bfe4-4c5a-a82d-66063fc3fc9f","n":4,"title":"القصة في الأدب العربي الحديث","passage":"تتنوع القصة العربية الحديثة في بنيتها الواقعية والرمزية وتقنيات الزمن، ولا يصح تعميم طريقة واحدة على كل الكتّاب. مثال مستقل ينظم راو حدثًا في ثلاثة مشاهد، ثم يعيد ترتيبها لإبراز مفاجأة؛ تتبدل تجربة القارئ مع البنية.","question":"ما الذي يتغير عند إعادة ترتيب مشاهد القصة؟","correct":"طريقة تلقي القارئ للتسلسل والنتيجة","wrong":["الاسم النحوي للشخصية","جنس اللغة","عدد الكتب المنشورة"],"practice":"قارن قصة صحيحة المصدر بأخرى من إنشائك من حيث العقدة والترتيب.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"2b543444-bfe4-4c5a-a82d-66063fc3fc9f","n":5,"title":"في البيت الجديد لنجيب محفوظ","passage":"يحتاج النص «في البيت الجديد» المنسوب إلى نجيب محفوظ إلى نسخته المقررة لتحديد شخصياته والأحداث وما يرمز إليه المكان، ولا يجوز إنشاء حوار ثم نسبته للمؤلف. مثال مستقل تصف أسرة نقل أثاثها إلى منزل جديد وتأملها معنى الانتقال، ولا يمثل العمل.","question":"ما الدليل الصحيح على دلالة البيت في النص؟","correct":"أحداث ووصف موثق من القصة","wrong":["العنوان وحده","حوار مصنوع","موقف من رواية أخرى"],"practice":"استخرج من النص الأصلي وصفًا للمكان وفسر علاقته بتصرف شخصية.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"2b543444-bfe4-4c5a-a82d-66063fc3fc9f","n":6,"title":"النخاسة","passage":"يشير مفهوم النخاسة إلى الاتجار بالبشر واستعبادهم تاريخيًا، وهو انتهاك لكرامتهم وحقوقهم. عند قراءة نص أدبي يحمل هذا العنوان يجب توثيق النص وتحديد صوت الضحية والراوي، مع تجنب اختلاق وقائع أو تصوير الاستغلال على أنه مبرر.","question":"ما المنظور النقدي المسؤول عند دراسة هذا الموضوع؟","correct":"فحص الانتهاك وكرامة الأشخاص بسياق موثق","wrong":["تبرير الاستغلال","تجاهل الضحايا","اختلاق خبر"],"practice":"حلل نصًا موثقًا حول الحرية والكرامة وناقش صوت المتكلم دون تفاصيل مؤذية أو غير مثبتة.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"2b543444-bfe4-4c5a-a82d-66063fc3fc9f","n":7,"title":"المسرحية في الأدب العربي","passage":"تبنى المسرحية على حوار وفعل وصراع وتحول في المواقف، وقد تضيف تعليمات الأداء عناصر مرئية وصوتية. يختلف المشهد عن القصة التي تنقل فيها بعض الأحداث بواسطة راو. نموذج مستقل يدور حول خلاف بشأن تنظيم نشاط ثم حل تفاوضي.","question":"أي عنصر يميز العرض الدرامي في المثال؟","correct":"حوار وأفعال تُظهر تغير الموقف","wrong":["غياب الشخصيات","التقطيع العروضي","المفعول المطلق"],"practice":"حوّل فقرة سردية من إنشائك إلى مشهد حوار من ثلاث شخصيات مع إرشادات مسرحية.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"2b543444-bfe4-4c5a-a82d-66063fc3fc9f","n":8,"title":"العودة إلى الكهف","passage":"لا يثبت عنوان «العودة إلى الكهف» أنه استمرار لعمل مسرحي معين أو أنه يروي وقائع دينية؛ يحتاج تحليل النص المدرسي الصحيح والتثبت من المؤلف. مثال مستقل يناقش متعلم معنى العودة إلى مكان قديم بعد سنوات، ولا ينسب إلى أي مسرحية.","question":"ما الذي يثبت هوية نص يحمل عنوانًا مشابهًا لعمل آخر؟","correct":"اسم المؤلف والنص المحقق والسياق","wrong":["تشابه العنوان فقط","تخمين النهاية","إضافة شخصية من عمل آخر"],"practice":"اقرأ النص المقرر واستخرج مشهدًا يوضح معنى العودة وتطور الشخصية.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"2b543444-bfe4-4c5a-a82d-66063fc3fc9f","n":9,"title":"عمل المشتقات: اسم الفاعل وصيغ المبالغة والصفة المشبهة باسم الفاعل","passage":"تختلف المشتقات في معناها وعملها النحوي وشروطه؛ «كاتب» اسم فاعل، و«غفّار» صيغة مبالغة في سياقاتها اللغوية، و«حَسَن» صفة مشبهة. لا يُحكم بعمل المشتق في الجملة من شكله وحده دون شروط الاعتماد والمعنى.","question":"ما الصيغة الصرفية لكلمة «كاتب»؟","correct":"اسم فاعل","wrong":["اسم مفعول","صيغة مبالغة","حرف جر"],"practice":"صغ جملًا بمشتقات متنوعة ثم ادرس شروط عملها من مرجع نحوي موثوق.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"2b543444-bfe4-4c5a-a82d-66063fc3fc9f","n":10,"title":"مهارة كتابة مقال تحليلي لنص سردي","passage":"تبدأ المقالة التحليلية بقضية تخص السرد، وتستدل على زاوية الراوي والعقدة والزمن بمقاطع صحيحة من النص، ثم تناقش أثرها دون إعادة الحكاية كاملة. في مثال مستقل يحدد طالب كيف غيّر حذف مشهد ترتيب توقع القارئ.","question":"ما الفرق بين التحليل وتلخيص القصة؟","correct":"التحليل يفسر وظيفة العناصر بدليل","wrong":["التحليل يكرر الأحداث فقط","التحليل يلغي الشواهد","التحليل يحذف الزمان"],"practice":"اكتب مقالًا من ثلاث فقرات عن نص سردي موثق مع شاهدين وتحليل أثر البناء.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"7d0a3749-fe06-4b93-ba87-34247cbc4a42","n":1,"title":"النهضة العربية","passage":"تدرس النهضة العربية عبر تحولات التعليم والنشر والتواصل وأشكال الأدب وفق أزمنة وأمكنة متنوعة، ولا تفسر كلها بسبب واحد. يعتمد الباحث على كتب ومواد مؤرخة وشواهد من نصوص صحيحة النسبة.","question":"ما الذي يضبط تفسير تحولات النهضة أدبيًا؟","correct":"مصادر مؤرخة ومقارنة نصوص","wrong":["عنوان عام فقط","حكاية مجهولة","تعميم شاعر واحد"],"practice":"أنشئ خطًا زمنيًا لتطور أدبي موثق يذكر تاريخين ونصين ومصدرين.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"7d0a3749-fe06-4b93-ba87-34247cbc4a42","n":2,"title":"المدارس الأدبية","passage":"تتداخل السمات الفنية بين الكلاسيكية والرومنسية والواقعية وغيرها؛ لا يصح تصنيف كل قصيدة عن الطبيعة ضمن مدرسة محددة بلا تحليل. يجب النظر إلى الصوت والصورة والبناء والعلاقة بالسياق التاريخي.","question":"ما الدليل الأدق لتصنيف اتجاه أدبي؟","correct":"تحليل سمات النص وسياقه الموثق","wrong":["تاريخ نشر واحد فقط","اسم الشاعر دون نص","ذكر منظر طبيعي وحده"],"practice":"قارن نصين من اتجاهين مختلفين بشواهد على اللغة والبناء والموضوع.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"7d0a3749-fe06-4b93-ba87-34247cbc4a42","n":3,"title":"أسلوب النداء","passage":"يستخدم النداء أداة مثل «يا» لمخاطبة شخص أو جماعة، وقد يخرج إلى غرض بلاغي كالتنبيه أو التحسر بحسب السياق. في «يا طالبَ العلمِ، اجتهدْ» المنادى مضاف منصوب، ونراعي نوع المنادى وعلامته.","question":"ما نوع المنادى في «يا طالب العلم»؟","correct":"منادى مضاف منصوب","wrong":["علم مفرد مبني","مفعول مطلق","بدل مرفوع"],"practice":"اكتب أربع جمل نداء بأنواع مختلفة وفسّر الغرض والضبط.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"7d0a3749-fe06-4b93-ba87-34247cbc4a42","n":4,"title":"أسلوب الشرط","passage":"في «إنْ تجتهدْ تنجحْ» أداة الشرط «إن» تجزم فعلين مضارعين في هذا التركيب، ويترابط فعل الشرط وجوابه بعلاقة معلنة. تختلف الأدوات الجازمة وغير الجازمة وأحكام اقتران الجواب بالفاء وفق القاعدة.","question":"ما أداة الشرط في «إن تجتهد تنجح»؟","correct":"إنْ","wrong":["لن","ما التعجبية","قد"],"practice":"كوّن ثلاث جمل شرط متنوعة مع إعراب الفعل والجواب.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"7d0a3749-fe06-4b93-ba87-34247cbc4a42","n":5,"title":"الصورة الشعرية","passage":"تنتج الصورة الشعرية أثرها من اختيار ألفاظ وعلاقات حسية ومجازية مرتبطة بعاطفة المتكلم. في «صافحَ النسيمُ أوراقَ الشجر» استعارة تشخص النسيم، ولا تعد وصفًا حرفيًا. يفسر الناقد أثرها في رسم الهدوء.","question":"ما الصورة في «صافح النسيم أوراق الشجر»؟","correct":"استعارة تقوم على التشخيص","wrong":["طباق","جناس","حقيقة علمية"],"practice":"أنشئ صورتين شعريتين بأسلوبين مختلفين ثم فسر علاقتهما بالمعنى.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"7d0a3749-fe06-4b93-ba87-34247cbc4a42","n":6,"title":"مهارة كتابة مقال تحليلي لنص أدبي","passage":"المقال التحليلي يحتاج أطروحة ومقتطفًا صحيح المصدر وتفسيرًا للصورة أو البنية وخاتمة منضبطة بالاستدلال. لا يكتفي الطالب بإطلاق أحكام «جميل» أو «ممتاز» دون شواهد، ولا يختلق أبياتًا أو حوارًا.","question":"ما الذي يثبت الحكم الفني في المقال؟","correct":"شاهد من النص مع تعليل أثره","wrong":["انطباع مطلق","تكرار عنوان الدرس","إضافة اقتباس غير موجود"],"practice":"اكتب مقالًا تحليليًا حول نص موثق يتضمن دعوى ودليلين وقراءة بديلة.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"cdeda136-f9e0-4f74-b4fa-ff2a126d70f8","n":1,"title":"النقد ومذاهبه","passage":"تتنوع مقاربات النقد بين وصف خصائص اللغة والبناء وتحليل السياق الاجتماعي والنفسي وغيرها حسب المناهج، ويجب توضيح سؤال كل مقاربة وأدلتها وحدودها. في مثال مستقل يتناول ناقد صورة أدبية من زاوية لغوية وآخر من زاوية التلقي.","question":"ما الذي يميز المقارنة بين منهجين نقديين؟","correct":"تحديد السؤال والشاهد وحدود التفسير","wrong":["اسم المنهج فقط","إلغاء النص","الحكم دون دليل"],"practice":"حلل فقرة أصلية من منظورين ووضح ما يفسره كل منظور وما قد يفوته.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"cdeda136-f9e0-4f74-b4fa-ff2a126d70f8","n":2,"title":"المناهج النقدية","passage":"يعتمد النقد السياقي على معلومات تاريخية موثقة، بينما يفحص التحليل البنيوي العلاقات داخل النص وفق المنهج المختار؛ وقد تتكامل المناهج ولكن لا تساوي جميع القراءات في قوة الدليل. نذكر افتراضات التحليل قبل النتيجة.","question":"ما الذي يمنع القراءة النقدية من التعسف؟","correct":"وضوح المنهج والاستدلال النصي","wrong":["تغيير الشواهد","تخمين قصد المؤلف","إعلان النتيجة مسبقًا"],"practice":"ضع سؤالًا نقديًا يناسب نصًا من اختيارك مع ثلاثة شواهد ومحدودية للمنهج.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"cdeda136-f9e0-4f74-b4fa-ff2a126d70f8","n":3,"title":"شروط صناعة الشعر للمرصفي","passage":"تستلزم دراسة شروط صناعة الشعر عند المرصفي نصه النقدي الصحيح ومرجعه المحقق؛ لا يجوز اختراع قائمة شروط ونسبتها إليه. تدريب مستقل يراجع قصيدة من حيث سلامة اللغة والإيقاع والصورة بوصفها معايير تعليمية عامة لا اقتباسًا من المؤلف.","question":"كيف نعرف الشروط التي عدّدها المرصفي فعلًا؟","correct":"بالرجوع إلى النص النقدي المحقق","wrong":["باختراع قائمة مألوفة","من عنوان الدرس فقط","من شعر غير موثق"],"practice":"انقل تعريفًا قصيرًا صحيح المصدر من النص النقدي ثم طبقه على شاهد شعري موثق.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"cdeda136-f9e0-4f74-b4fa-ff2a126d70f8","n":4,"title":"شوقي في الميزان (توطئة)","passage":"عنوان «شوقي في الميزان» يشير إلى ممارسة نقدية تحتاج تحديد الكاتب والنص الأصلي للتعرف إلى معيار تقويم شعر أحمد شوقي؛ لا يصح تخمين موقف الناقد من العنوان. في مثال مستقل يوازن قارئ بين قوة الصورة وبناء الحجة في قصيدة موثقة.","question":"ما الذي يلزم قبل نسبة حكم نقدي عن شوقي إلى ناقد؟","correct":"التحقق من النص وصاحب الحكم ومعياره","wrong":["توقع المدح أو الذم","عنوان وحده","اقتباس غير موجود"],"practice":"استخرج من التوطئة المقررة دعوى نقدية موثقة ثم ناقش دليلها وحدودها.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"cdeda136-f9e0-4f74-b4fa-ff2a126d70f8","n":5,"title":"الشعر المهموس","passage":"قد تستخدم عبارة «الشعر المهموس» في خطاب نقدي للدلالة على نبرة أو طريقة تعبير ضمن سياق خاص، ولا يجوز إسناد تعريف قاطع لناقد مجهول دون مرجعه. يدرس الطالب تغير الصوت والألفاظ والموضوع من نص صحيح.","question":"ما الطريق الصحيح لفهم مصطلح نقدي قد تتعدد دلالاته؟","correct":"الرجوع إلى تعريف صاحبه وسياق استعماله","wrong":["التخمين من اللفظ","اعتبار كل شعر هادئ واحدًا","إغفال المصدر"],"practice":"حدد معنى المصطلح في النص النقدي المدرسي بدليل لفظي، ثم قارنه بمثال من إنشاءك.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"cdeda136-f9e0-4f74-b4fa-ff2a126d70f8","n":6,"title":"ميلاد السرد وتطوره","passage":"تتغير أشكال السرد مع وسائل التدوين والطباعة وتنوع الجمهور، وتتطور تقنيات الزمن والراوي والعقدة بطرق متفاوتة؛ لا يصح الاعتقاد بأن نوعًا نشأ فجأة من دون مقدمات موثقة. في مثال مستقل يعيد كاتب الحدث نفسه بصوت شاهد وصوت مشارك.","question":"ما العنصر الذي يظهر تغير تقنية السرد في المثال؟","correct":"تغير زاوية الراوي","wrong":["تغيير اسم الورق","تطابق الأصوات","عدد الأسطر فقط"],"practice":"قارن نصين سرديين مؤرخين من حيث الراوي وبناء الزمن مع توثيق.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"cdeda136-f9e0-4f74-b4fa-ff2a126d70f8","n":7,"title":"مراجعة البحور الصافية","passage":"يطلق في العروض «البحور الصافية» على بحور تقوم في أصل نسقها على تكرار تفعيلة واحدة مثل المتقارب والكامل والرمل ضمن التصنيف المدرسي، ويستلزم التطبيق التمييز بين الأصل والزحافات المستعملة.","question":"ما التفعيلة الأصلية للبحر المتقارب؟","correct":"فعولن","wrong":["مستفعلن وحدها","مفاعلتن وحدها","مفعولات وحدها"],"practice":"قارن مثالين موثقين على بحرين صافيين بكتابة عروضية وتفعيلات.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"cdeda136-f9e0-4f74-b4fa-ff2a126d70f8","n":8,"title":"عمل المصدر","passage":"قد يعمل المصدر عمل فعله في مواضع مخصوصة وبشروط، مثل دلالته على الحدث مع إمكان إضافة فاعل أو مفعول بحسب التركيب. لا يصح إعراب كل اسم على وزن المصدر عاملًا دون مراعاة السياق النحوي.","question":"ما الشرط الأول لتحليل عمل المصدر؟","correct":"دراسة معناه وعلاقته بمعمولاته في التركيب","wrong":["عد الحروف","لون الكتاب","التنوين وحده دائمًا"],"practice":"حلل من مرجع نحوي مثالين لمصدر عامل ومصدر غير عامل مع التعليل.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"cdeda136-f9e0-4f74-b4fa-ff2a126d70f8","n":9,"title":"عمل اسم المفعول","passage":"اسم المفعول مشتق للدلالة على ما وقع عليه الفعل، وقد يعمل عمل فعله المبني للمجهول وفق شروط السياق والاعتماد. في «الكتابُ مقروءٌ» نفهم المعنى الوصفي أولًا، ثم نراجع عمل المشتق في أمثلة مشروحة.","question":"ما معنى اسم المفعول في «الكتاب مقروء»؟","correct":"ما وقع عليه فعل القراءة","wrong":["من قام بالقراءة","حرف جر","فعل أمر"],"practice":"اختر مثالين موثقين لعمل اسم المفعول مع تحديد نائب الفاعل وشروط الاعتماد.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"cdeda136-f9e0-4f74-b4fa-ff2a126d70f8","n":10,"title":"مهارة كتابة مقال تحليلي لنص نقدي","passage":"يحدد المقال النقدي دعوى الناقد ومعياره وشاهده، ثم يفحص قوة الحجة ويقارنها بقراءة بديلة عند الحاجة. لا يكفي نقل رأي قديم بوصفه حقيقة مطلقة أو اختلاق قول للمؤلف.","question":"ما أساس تقويم رأي نقدي في مقال تحليلي؟","correct":"تحديد المعيار والشاهد ومناقشة الاستدلال","wrong":["عدد كلمات الرأي","اسم صاحبه وحده","تكرار الحكم"],"practice":"اكتب تحليلًا لفقرة نقدية صحيحة المصدر يتضمن أطروحة ودليلًا واعتراضًا وخاتمة.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"}]'::jsonb)
 AS x(cid uuid,unit uuid,n integer,title text,passage text,question text,correct text,wrong text[],practice text,old text)
 LOOP
  SELECT l.id,l.content INTO STRICT target_id,prior
  FROM public.lessons l JOIN public.units u ON u.id=l.unit_id
  JOIN public.grades g ON g.id=u.grade_id
  JOIN public.curricula c ON c.id=g.curriculum_id
  JOIN public.countries co ON co.id=c.country_id
  WHERE co.code='MR' AND c.id=r.cid
    AND g.grade_number=13 AND u.semester IS NULL AND u.id=r.unit
    AND l.sort_order=r.n AND l.title=r.title AND l.status='published'
  FOR UPDATE OF l;

  SELECT count(*) INTO hasprogress FROM public.student_lesson_progress WHERE lesson_id=target_id;
  IF hasprogress<>0 THEN RAISE EXCEPTION 'MR_G13_ARTS_HAS_PROGRESS_%',r.title; END IF;
  SELECT count(*) INTO hasprogress FROM public.lesson_activity_attempts att
    JOIN public.lesson_activities a ON a.id=att.activity_id WHERE a.lesson_id=target_id;
  IF hasprogress<>0 THEN RAISE EXCEPTION 'MR_G13_ARTS_HAS_ATTEMPTS_%',r.title; END IF;
  IF char_length(coalesce(prior,''))>=350 THEN RAISE EXCEPTION 'MR_G13_ARTS_ALREADY_CONTENT_%',r.title; END IF;
  SELECT count(*) INTO nact FROM public.lesson_activities
    WHERE lesson_id=target_id AND content->>'origin'=r.old AND answer='{}'::jsonb;
  IF nact<>3 THEN RAISE EXCEPTION 'MR_G13_ARTS_EXPECTED_3_PLACEHOLDERS_%',r.title; END IF;

  UPDATE public.lessons SET
    content='ضاديوم — إثراء تعليمي أصلي للسنة الرابعة الإعدادية في موريتانيا. هذا ليس نص الكتاب المعتمد ولا تأكيدًا لمطابقة جميع الفصول؛ الاسم مستورد ويلزم تحقق وزاري.'
    ||E'\n\n'||'عنوان الدرس: '||r.title
    ||E'\n\n'||'هدف التعلم: أن يشرح المتعلم فكرة أو قاعدة من المجال، ويحلل قرينة أو شاهدًا صحيح النسبة، ويكتب استجابة جديدة تستند إلى دليل.'
    ||E'\n\n'||'شرح وتطبيق أصلي: '||r.passage
    ||E'\n\n'||'سؤال فهم: '||r.question
    ||E'\n\n'||'تطبيق كتابي مستقل: '||r.practice
    ||E'\n\n'||'التمايز: دعم بقائمة مفردات وخطوات تحليل أساسية، ومستوى متوسط يبرر الاختيار، ومستوى متقدم يقارن بين تفسيرين أو يختبر دقة المصدر. يتولى المعلم مراجعة مهام الكتابة.'
    ||E'\n\n'||'تحذير المصدر: لا تُنسب أمثلة ضاديوم إلى شاعر أو مؤرخ أو نص ديني؛ راجع المصدر المعتمد أولًا.'
    ||E'\n\n'||'المحتوى السابق المحفوظ: '||coalesce(prior,''),
    updated_at=now() WHERE id=target_id;

  UPDATE public.lesson_activities SET
    prompt='اقرأ النص التدريبي المستقل، واستخرج منه الفكرة أو الشاهد الذي تستند إليه الإجابة.',
    content=content||jsonb_build_object('origin','DADYOOM_MR_G13_ARTS_REMAINING_26_20261009','previousOrigin',r.old,
      'text',r.passage,'notOfficialBook',true,'sourceVerification','pending')
    WHERE lesson_id=target_id AND activity_type='reading'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  UPDATE public.lesson_activities SET prompt=r.question,
    content=content||jsonb_build_object('origin','DADYOOM_MR_G13_ARTS_REMAINING_26_20261009','previousOrigin',r.old,
       'text',r.question,'notOfficialBook',true,'sourceVerification','pending',
       'options',CASE (r.n%4)
       WHEN 0 THEN jsonb_build_array(r.correct,r.wrong[1],r.wrong[2],r.wrong[3])
       WHEN 1 THEN jsonb_build_array(r.wrong[1],r.correct,r.wrong[2],r.wrong[3])
       WHEN 2 THEN jsonb_build_array(r.wrong[1],r.wrong[2],r.correct,r.wrong[3])
       ELSE jsonb_build_array(r.wrong[1],r.wrong[2],r.wrong[3],r.correct) END),
    answer=jsonb_build_object('correct',r.correct)
    WHERE lesson_id=target_id AND activity_type='multiple_choice'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  UPDATE public.lesson_activities SET prompt=r.practice,
    content=content||jsonb_build_object('origin','DADYOOM_MR_G13_ARTS_REMAINING_26_20261009','previousOrigin',r.old,
     'text',r.practice,'notOfficialBook',true,'sourceVerification','pending',
     'humanReviewRequired',true)
    WHERE lesson_id=target_id AND activity_type='writing'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  SELECT count(*) INTO nact FROM public.lesson_activities
   WHERE lesson_id=target_id AND content->>'origin'='DADYOOM_MR_G13_ARTS_REMAINING_26_20261009';
  IF nact<>3 THEN RAISE EXCEPTION 'MR_G13_ARTS_ACTIVITY_UPDATE_FAILED_%',r.title; END IF;
 END LOOP;
END $dadyoom$;